#!/bin/bash
set -e
TOKEN=$(docker exec chirothintrackerreact_appserver_1 drush ctt-patient-intake:invite-issue 1 2>/dev/null | head -1)
BODY="{\"token\":\"$TOKEN\",\"fields\":{\"field_first_name\":\"Testy\",\"field_last_name\":\"McTest\",\"field_email_address\":\"testy@example.com\",\"field_phone_number\":\"555-123-4567\",\"field_gender\":\"F\",\"field_date_of_birth\":\"1990-05-01\",\"field_program_start_date\":\"2026-09-26\",\"field_weight\":180,\"field_daily_activity_level\":\"2\",\"field_medical_eligibility\":\"0\",\"field_high_cholesterol\":\"1\",\"field_diabetes\":\"0\",\"field_high_blood_pressure\":\"0\",\"field_thyroid_condition\":\"0\",\"field_gall_bladder\":\"0\",\"field_emotional_eater\":\"0\",\"field_mailing_address\":{\"address_line1\":\"123 Main St\",\"locality\":\"Columbus\",\"administrative_area\":\"OH\",\"postal_code\":\"43215\",\"country_code\":\"US\"},\"field_emergency_contact_name\":\"Bucky McTest\",\"field_emergency_contact_phone\":\"614-555-0100\",\"field_consent\":\"Testy McTest\",\"field_consent_consumption\":1}}"
curl -s -w '\nHTTP %{http_code}\n' -X POST -H 'Content-Type: application/json' -d "$BODY" "http://127.0.0.1:55162/api/intake/submit"
docker exec chirothintrackerreact_appserver_1 drush sql:query "SELECT status FROM ctt_patient_intake_invite WHERE token='$TOKEN'" --extra=--skip-column-names 2>/dev/null || true